from config_loader import load_config

def test_ignores_blank_lines():
    """Verify load_config ignores blank lines."""
    result = load_config("\nA=1\n\nB=2\n")
    assert result == {"A": "1", "B": "2"}


def test_ignores_lines_starting_with_hash():
    """Verify load_config ignores lines starting with #."""
    result = load_config("# comment\nA=1\n# another comment\nB=2\n")
    assert result == {"A": "1", "B": "2"}


