    """Verify load_config strips whitespace around keys."""
    result = load_config("  A  =  1  ")
    assert result == {"A": "1"}


def test_strips_whitespace_around_values():
    """Verify load_config strips whitespace around values."""
    result = load_config("A=  1  ")
    assert result == {"A": "1"}


